import {tankDrawingModel} from './tank-drawing-model.js';
import {supportDrawingSheet} from './tank-support-drawing.js';
import {esc,fmt} from './tank-visuals.js';
const table=(headers,rows)=>`<table><thead><tr>${headers.map(v=>'<th>'+esc(v)+'</th>').join('')}</tr></thead><tbody>${rows.map(row=>'<tr>'+row.map(v=>'<td>'+esc(v??'待核')+'</td>').join('')+'</tr>').join('')}</tbody></table>`;
const number=v=>Number.isFinite(v)?fmt(v,3):'待核';
export function supportConstructionPages(r,page){
  const m=tankDrawingModel(r),p=m?.support;if(!p)throw Error('目前支承配置尚未完成，請先修正支承頁。');
  const f=p.formed,parts=m.parts.filter(b=>b.assembly===p.id),welds=r.fabricationPlan.welds.filter(w=>w.assembly===p.id),diagram=n=>supportDrawingSheet(r,n).replace('<svg ','<svg style="display:block;width:100%;height:auto;max-height:390px" '),pages=[];
  pages.push(page('支承放樣與底板',`<h1>${esc(p.name)} · 放樣與底板</h1><p>模型 ${m.revision}；由目前專案產生。${p.sourceDiff.length?'已有尺寸修改，不再當作與原圖完全相同。':''}</p>${diagram(1)}${table(['共同板號','目前規格','總數','已計kg'],parts.filter(b=>['P1','P6'].includes(b.localId)).map(b=>[b.id,b.spec,b.quantity,number(b.weight)]))}<p>核對A端TL、兩組中心${p.stations.map(number).join('／')}、中心距${number(p.stations[1]-p.stations[0])}；槽軸至板底${number(-p.floor)}。孔列偏置${p.layout.holeAxialOffset===null?'未填，不得直接按示意中心線鑽孔':number(p.layout.holeAxialOffset)+' mm'}。</p>`));
  pages.push(page('支承預彎與捲製',`<h1>耐磨板 · 預彎、捲製與試貼</h1><p>模型 ${m.revision}；${p.id}.P4-1／-2對應BOM ${p.id}.P4。</p>${diagram(2)}${table(['目前設定／推導','共同值'],[['先備板',number(f.blankLength)+' × '+number(p.parts.find(x=>x.kind==='rolled').width)+' × t'+number(f.thickness)],['成形角／中面R',number(f.angle)+'° / '+number(f.meanRadius)],['內／中／外弧長',number(f.insideLength)+' / '+number(f.formedLength)+' / '+number(f.outsideLength)],['先備與中面差',number(f.delta)+' mm；差值處理待核']])}<p>標號備料 → 確認成形及切端基準 → 依核定捲製程序預彎 → 捲製並在實際筒體試貼 → 確認角度與兩邊位置後修邊。</p>`));
  pages.push(page('支承組立與焊接',`<h1>定位、點固與焊接</h1><p>模型 ${m.revision}；先確認異形板詳圖再試拼，複核中心距、槽軸高與耐磨板試貼，依核定點固及WPS施焊。</p>${table(['共同焊號','接合對象','單道／總長mm','焊腳／厚度','WPS'],welds.map(w=>[w.id,w.a+' → '+w.b,number(w.eachLength)+' / '+number(w.length),number(w.size),w.wps||'待核']))}<p>腳底全周按2×（目前腳底寬＋板厚）換算；名目長度不含端部處理與起收弧修正。其他黃虛線只表示接合區，並非已核定連續焊範圍。</p><h2>支承BOM</h2>${table(['編號','材質','目前規格','數量','已計kg'],parts.map(b=>[b.id,b.material,b.spec,b.quantity,number(b.weight)+(b.weightBasis==='blank'?'（先備板）':'')]))}`));
  pages.push(page('支承待核與回填',`<h1>支承待核項與實測記錄</h1><p>模型 ${m.revision}；未知項目不補成零或假定可加工。</p>${table(['編號','具體缺項'],p.pending.map(x=>[x.id,x.text]))}<h2>施工回填</h2><p>核定圖號／版次：________________________</p><p>A組站位：____________ B組站位：____________</p><p>孔列偏置：____________ 實測槽軸高：____________</p><p>成形角／試貼：________________________</p><p>點固及焊後複測／異常：________________________</p><p>作業／核對人：________________ 日期：____________</p>`));return pages;
}
